import { describe, expect, it } from "@effect/vitest"
import { ConfigProvider, Context, Effect, FileSystem, Layer, Path, PlatformError } from "effect"
import { ChildProcess, ChildProcessSpawner } from "effect/process"
import { readFileSync } from "node:fs"
import * as NodeBin from "../src/internal/node-bin.js"

// Generated by npm's own cmd-shim 7.0.0 for a global `@anthropic-ai/claude-code` install (CRLF, as npm
// writes it), so the parser is tested against what npm actually produces.
const npmShim = readFileSync(new URL("./fixtures/cmd-shim/claude.cmd", import.meta.url), "utf8")
const node = "C:\\Program Files\\nodejs\\node.exe"
const search = { path: "C:\\Windows\\system32;C:\\Users\\owner\\AppData\\Roaming\\npm", pathExt: ".COM;.EXE;.BAT;.CMD" }

/** A Windows disk holding exactly `files`. */
const disk = (files: Readonly<Record<string, string>>) =>
  FileSystem.makeNoop({
    exists: (path) => Effect.succeed(Object.hasOwn(files, path)),
    readFileString: (path) => {
      const text = files[path]
      return text === undefined
        ? Effect.fail(PlatformError.systemError({ _tag: "NotFound", module: "FileSystem", method: "readFileString" }))
        : Effect.succeed(text)
    }
  })

const resolve = (files: Readonly<Record<string, string>>, command: string, args: ReadonlyArray<string> = []) =>
  NodeBin.resolveNodeBin(command, args, search, node).pipe(Effect.provideService(FileSystem.FileSystem, disk(files)))

describe("npm cmd-shim", () => {
  it("reads the Node script an npm shim runs", () => {
    expect(NodeBin.parseCmdShim(npmShim)).toEqual({
      nodeArgs: [],
      script: "node_modules\\@anthropic-ai\\claude-code\\cli.js"
    })
  })

  // A shebang with Node flags puts them between the program and the script.
  it("keeps the shim's Node arguments", () => {
    const withFlags = npmShim.replace(`"%_prog%"  "%dp0%`, `"%_prog%" --max-old-space-size=4096 "%dp0%`)
    expect(NodeBin.parseCmdShim(withFlags)?.nodeArgs).toEqual(["--max-old-space-size=4096"])
  })

  it("refuses a .cmd that is not an npm Node shim", () => {
    expect(NodeBin.parseCmdShim("@echo off\r\npython %~dp0\\tool.py %*\r\n")).toBeUndefined()
    // cmd-shim's shim for a non-Node shebang names the program and has no node.exe preference.
    expect(NodeBin.parseCmdShim(`@ECHO off\r\n"%~dp0\\tool.sh" %*\r\n`)).toBeUndefined()
  })
})

describe("Windows command resolution", () => {
  const npmDirectory = "C:\\Users\\owner\\AppData\\Roaming\\npm"

  it.effect("runs an npm shim's script with this Node instead of the .cmd", () =>
    Effect.gen(function*() {
      expect(yield* resolve({ [`${npmDirectory}\\claude.cmd`]: npmShim }, "claude", ["--version"])).toEqual({
        command: node,
        args: [`${npmDirectory}\\node_modules\\@anthropic-ai\\claude-code\\cli.js`, "--version"]
      })
    }))

  // The native installer's claude.exe is a real executable: spawn it as is, by its full path.
  it.effect("spawns a native .exe directly, first match on PATH winning", () =>
    Effect.gen(function*() {
      const files = { "C:\\Windows\\system32\\claude.exe": "", [`${npmDirectory}\\claude.cmd`]: npmShim }
      expect(yield* resolve(files, "claude", ["-p"])).toEqual({
        command: "C:\\Windows\\system32\\claude.exe",
        args: ["-p"]
      })
    }))

  it.effect("follows an explicit path to a shim", () =>
    Effect.gen(function*() {
      expect(yield* resolve({ "D:\\tools\\claude.cmd": npmShim }, "D:\\tools\\claude.cmd")).toEqual({
        command: node,
        args: ["D:\\tools\\node_modules\\@anthropic-ai\\claude-code\\cli.js"]
      })
    }))

  it.effect("fails on a .cmd it can't read as a Node shim, and on a .bat, never using a shell", () =>
    Effect.gen(function*() {
      const handWritten = yield* resolve({ [`${npmDirectory}\\tool.cmd`]: "@echo off\r\nperl tool.pl %*\r\n" }, "tool")
        .pipe(Effect.flip)
      expect(handWritten).toEqual(new NodeBin.NodeBinUnresolved({ command: "tool" }))
      const batch = yield* resolve({ [`${npmDirectory}\\tool.bat`]: "@echo off\r\n" }, "tool").pipe(Effect.flip)
      expect(batch._tag).toBe("NodeBinUnresolved")
    }))

  // Missing stays missing: the spawn then reports NotFound, as callers already handle.
  it.effect("leaves a command found nowhere unchanged", () =>
    Effect.gen(function*() {
      expect(yield* resolve({}, "agent-usage", ["limits"])).toEqual({ command: "agent-usage", args: ["limits"] })
    }))
})

describe("spawner", () => {
  const recording = () => {
    const spawned: Array<ChildProcess.Command> = []
    const spawner = ChildProcessSpawner.make((command) => {
      spawned.push(command)
      return Effect.die("recorded, not spawned")
    })
    return { spawned, layer: Layer.succeed(ChildProcessSpawner.ChildProcessSpawner, spawner) }
  }
  const windowsPath = Layer.effect(Path.Path, Effect.map(Path.Path, (path) => ({ ...path, sep: "\\" })))
    .pipe(Layer.provide(Path.layer))

  // Windows spells the variable `Path`: the layer must find it under that name too.
  const environment = ConfigProvider.layer(ConfigProvider.fromUnknown({ Path: search.path, PATHEXT: search.pathExt }))

  // The wrapped spawner over a recorder, a platform and a disk; built here, not provided to the test.
  const wrapped = (
    recorder: Layer.Layer<ChildProcessSpawner.ChildProcessSpawner>,
    platform: Layer.Layer<Path.Path>,
    files: Readonly<Record<string, string>>
  ) =>
    Layer.build(
      NodeBin.layer(node).pipe(
        Layer.provide(
          Layer.mergeAll(recorder, platform, Layer.succeed(FileSystem.FileSystem, disk(files)), environment)
        )
      )
    ).pipe(Effect.map((context) => Context.get(context, ChildProcessSpawner.ChildProcessSpawner)))

  const spawnWith = (platform: Layer.Layer<Path.Path>, files: Readonly<Record<string, string>>) => {
    const { layer, spawned } = recording()
    return Effect.scoped(Effect.gen(function*() {
      const spawner = yield* wrapped(layer, platform, files)
      yield* Effect.exit(spawner.spawn(ChildProcess.make("claude", ["--version"])))
      return spawned
    }))
  }

  it.effect("rewrites a shim on Windows", () =>
    Effect.gen(function*() {
      const [spawned] = yield* spawnWith(windowsPath, {
        "C:\\Users\\owner\\AppData\\Roaming\\npm\\claude.cmd": npmShim
      })
      expect(spawned).toMatchObject({ command: node })
    }))

  it.effect("leaves POSIX spawns untouched", () =>
    Effect.gen(function*() {
      const [spawned] = yield* spawnWith(Path.layer, {})
      expect(spawned).toMatchObject({ command: "claude", args: ["--version"] })
    }))

  it.effect("reports a .bat as not found, naming the command, without spawning anything", () =>
    Effect.gen(function*() {
      const { layer, spawned } = recording()
      const error = yield* Effect.scoped(Effect.gen(function*() {
        const spawner = yield* wrapped(layer, windowsPath, { "C:\\Users\\owner\\AppData\\Roaming\\npm\\tool.bat": "" })
        return yield* spawner.spawn(ChildProcess.make("tool", []))
      })).pipe(Effect.flip)
      expect(error).toMatchObject({ _tag: "PlatformError", reason: { _tag: "NotFound", pathOrDescriptor: "tool" } })
      expect(spawned).toEqual([])
    }))
})
